import React from "react";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

interface TaskListProps{
    tasks: Task[];
    markTaskAsDone: (id: number) => void;
}

const TaskList: React.FC<TaskListProps> = ({ tasks, markTaskAsDone }) => {
    return(
        <div>
            <h2>Task List</h2>

            {tasks.length === 0 ? (
                <p>No available tasks!</p>
            ) : (
                <ul>
                    {tasks.map((task) => (
                        <li key={task.id}>
                            <input
                                type = "checkbox"
                                checked = {task.doneFlag}
                                onChange = {() => markTaskAsDone(task.id, task.doneFlag)}
                            />
                            <strong style = {{ textDecoration: task.doneFlag ? "line-through" : "none" }}>
                                {task.text}
                            </strong>
                            {" - "}
                            {task.priority}
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default TaskList;
